# This formula is regenerated by the ankra-cli release workflow from
# packaging/homebrew/ankra.rb.tmpl in ankraio/ankra-cli. Manual edits here
# will be overwritten on the next release; change the template instead.
#
# There is deliberately no `version` stanza: `brew audit` fails a tap whose
# declared version it can already scan from the stable URL (redundant_version),
# and every release URL below carries the tag. That is why the URLs interpolate
# nothing - the release workflow substitutes the version into them directly.
class Ankra < Formula
  desc "Command-line interface for the Ankra Kubernetes platform"
  homepage "https://ankra.io"
  license "Apache-2.0"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.52.0/ankra-cli-darwin-arm64"
      sha256 "fc414b91e35cd2917c96c6768aebd544cfe44d2cde71b0f00855121a6f5cf097"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.52.0/ankra-cli-darwin-amd64"
      sha256 "77c4016c9e786097536c9cf809411becceda788fcd48bf7e3a112fe95331593f"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.52.0/ankra-cli-linux-arm64"
      sha256 "31c6a9175edb07a1e74136f965c5b76b6f2e3defa23aa406e65408463b65cc1d"
    end
    on_intel do
